import java.util.Scanner;
import java.util.Map;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int a = scanner.nextInt();
        int b = scanner.nextInt();
        int[] sorted = {a, b};
        java.util.Arrays.sort(sorted);
        int x = sorted[0];
        int y = sorted[1];

        int adjustment;
        if (x == 1) {
            adjustment = Math.min(y % 6, 6 - y % 6);
        } else if (x == 2) {
            Map<Integer, Integer> map = java.util.Map.of(2, 4, 3, 2, 7, 2);
            adjustment = map.getOrDefault(y, 0);
        } else {
            adjustment = (x & 1) * (y & 1);
        }
        System.out.println(x * y - adjustment);
        scanner.close();
    }
}
